export const command = {
  name: 'selectAllCellsAndHeaders',
  callback(_ref) {
    let {
      selection
    } = _ref;
    selection.markSource('keyboard');
    selection.selectAll(true, true, {
      disableHeadersHighlight: false
    });
    selection.markEndSource();
  }
};
